addCategory.example:
// client
const { Keybinds } = kcds.ui;

Keybinds.addCategory('roleplay', 'Roleplay');
Keybinds.add('emote_menu', { label: 'Emote menu', category: 'roleplay', key: 'f6' });

addCategory.exampleCs:
// client

Keybinds.AddCategory("roleplay", "Roleplay");
Keybinds.Add("emote_menu", new { label = "Emote menu", category = "roleplay", key = "f6" });

add.example:
// client
const { Keybinds } = kcds.ui;

Keybinds.add('radio', { label: 'Talk on the radio', key: 'f6', controller: 'xi_dpad_up' });
Keybinds.on('radio', 'both', (id, edge) => {
  kcds.core.Events.toServer('radio:talk', edge === 'down');
});

add.exampleCs:
// client

Keybinds.Add("radio", new { label = "Talk on the radio", key = "f6", controller = "xi_dpad_up" });
Keybinds.On("radio", "both", (JsValue id, JsValue edge) =>
{
    Events.ToServer("radio:talk", edge.AsString() == "down");
});

get.example:
// client: tell the player which key opens the menu
const { Keybinds, Key, Hud } = kcds.ui;

const menu = Keybinds.get('emote_menu');
if (menu?.key) {
  Hud.showNotification(`Press ${Key.getLabel(menu.key)} for emotes`);
}

get.exampleCs:
// client: tell the player which key opens the menu

var menu = Keybinds.Get("emote_menu");
if (menu["key"])
{
    Hud.ShowNotification($"Press {Key.GetLabel(menu["key"])} for emotes");
}

list.example:
// client
for (const action of kcds.ui.Keybinds.list()) {
  console.log(`${action.label}: ${action.keys.join(', ') || 'unbound'}`);
}

list.exampleCs:
// client
foreach (var action in Keybinds.List())
{
    Log.Info($"{action["label"]}: {((string.IsNullOrEmpty(action["keys"].Call("join", ", ").AsString()) ? "unbound" : action["keys"].Call("join", ", ").AsString()))}");
}

set.example:
// client
const { Keybinds } = kcds.ui;

Keybinds.set('radio', { key: 'f7', controller: 'xi_y' });
Keybinds.set('emote_menu', { controller: null });

set.exampleCs:
// client

Keybinds.Set("radio", new { key = "f7", controller = "xi_y" });
Keybinds.Set("emote_menu", new { controller = Sdk.Null });

on.example:
// client
const { Keybinds } = kcds.ui;

Keybinds.add('emote_menu', { label: 'Emote menu', key: 'f6' });
Keybinds.on('emote_menu', () => kcds.core.Events.toServer('emotes:open'));

on.exampleCs:
// client

Keybinds.Add("emote_menu", new { label = "Emote menu", key = "f6" });
Keybinds.On("emote_menu", new Action(() => Events.ToServer("emotes:open")));
